import{_ as r,o as t,c as a,a2 as e}from"./chunks/framework.CnHmQiA8.js";const u=JSON.parse('{"title":"导入题目与知识点","description":"","frontmatter":{"title":"导入题目与知识点","outline":[2,3]},"headers":[],"relativePath":"guide/import.md","filePath":"guide/import.md","lastUpdated":1795437342000}'),n={name:"guide/import.md"};function s(d,o,l,i,g,c){return t(),a("div",null,[...o[0]||(o[0]=[e('<h1 id="导入题目与知识点" tabindex="-1">导入题目与知识点 <a class="header-anchor" href="#导入题目与知识点" aria-label="Permalink to &quot;导入题目与知识点&quot;">​</a></h1><p>除了从零手动录入，软件提供从 <strong>Word 文档</strong>、<strong>图片（AI 识图）</strong> 与 <strong>墨案</strong> 导入题目或知识点，尽量保留原有公式、表格、插图和题号结构。</p><h2 id="_1-从-word-文档导入" tabindex="-1">1. 从 Word 文档导入 <a class="header-anchor" href="#_1-从-word-文档导入" aria-label="Permalink to &quot;1. 从 Word 文档导入&quot;">​</a></h2><h3 id="入口" tabindex="-1">入口 <a class="header-anchor" href="#入口" aria-label="Permalink to &quot;入口&quot;">​</a></h3><ul><li><strong>整份新建</strong>：在首页点击 <strong>从 Word 文档新建</strong>，或直接双击文件列表中的 <code>.docx</code> 文档。</li><li><strong>追加导入</strong>：在编辑界面点击 <strong>导入题目 ▾ → Word 文档…</strong>，导入的题目会插入到当前选中内容之后。</li></ul><h3 id="识别规则与保留内容" tabindex="-1">识别规则与保留内容 <a class="header-anchor" href="#识别规则与保留内容" aria-label="Permalink to &quot;识别规则与保留内容&quot;">​</a></h3><ul><li><strong>组卷网文档直导</strong>：从组卷网下载的题目文档可以直接导入；题组（材料 + 若干小题）会自动整理为综合题并共用答案与解析；短标题、背景材料、配图、选项、小问都会识别；难度系数会自动换算为难度等级（<code>0.7</code> 以上 A、<code>0.5～0.7</code> B、低于 <code>0.5</code> C）；“学校:___ 姓名:___”及“系统分组”等干扰行会自动清理。</li><li><strong>普通题集 / 教案文档</strong>：使用“物理排版”样式的文档按样式精确识别；其他文档会按 <code>1.</code> 题号、<code>A.</code> 选项、<code>【答案】</code>、<code>【解析】</code> 等常见标记智能切分。</li><li><strong>格式保留</strong>：导入时会保留 MathType / EQ 域 / Word 原生公式、形状示意图、表格（合并单元格、列宽、底纹）、加粗、文字颜色与字体（自动归类为宋 / 黑 / 楷 / 仿宋）。</li><li><strong>物理教学案预设特性</strong>：导入时会自动将 <code>【详解】</code> 统一改为 <code>【解析】</code>，解析文字统一为黑色，并保留知识梳理中的红色、加粗与下划线标记，同时自动识别作业单。</li></ul><h2 id="_2-从图片导入-交给-ai-识别" tabindex="-1">2. 从图片导入（交给 AI 识别） <a class="header-anchor" href="#_2-从图片导入-交给-ai-识别" aria-label="Permalink to &quot;2. 从图片导入（交给 AI 识别）&quot;">​</a></h2><p>手头只有纸质试卷照片、教辅扫描页或截图时，可以使用 <strong>导入题目 ▾ → 图片（交给 AI 识别）…</strong>：</p><h3 id="基本流程-通用-ai-方式" tabindex="-1">基本流程（通用 AI 方式） <a class="header-anchor" href="#基本流程-通用-ai-方式" aria-label="Permalink to &quot;基本流程（通用 AI 方式）&quot;">​</a></h3><ol><li><strong>放入图片</strong>：点击选择图片、直接拖入，或在窗口中按 <code>Ctrl+V</code> 粘贴截图。</li><li><strong>核对插图框选</strong>：软件会在本地自动框出图中的插图（不依赖网络），并按阅读顺序标为 <code>[图1]</code>、<code>[图2]</code> 与识别结果对应。框可以拖动、拖拽四角微调或删除；如有漏框，在图上随手拖出一个框即可自动收紧到图形边缘。</li><li><strong>复制指令给 AI</strong>：点击右侧 <strong>复制给 AI 的指令</strong>，连同题目图片一起发给任意擅长识图的 AI（例如 WorkBuddy、豆包、Kimi 等）。</li><li><strong>粘贴结果与即时检查</strong>：把 AI 返回的代码块内容粘贴回软件右侧，下方会立刻显示识别出几道题、是否存在无法转换的公式或尚未框选的插图，核对无误后点击导入。</li></ol><div class="tip custom-block"><p class="custom-block-title">插图处理同步完成</p><p>导入窗口默认开启 <strong>插图变清晰</strong>，可自动清理灰底杂点并对小图超分放大 3 倍；勾选 <strong>去白底</strong> 或点击 <strong>一键加深</strong> 后，点选插图还能实时对比处理前后的效果。</p></div><h3 id="workbuddy-一键自动识别-免复制粘贴" tabindex="-1">WorkBuddy 一键自动识别（免复制粘贴） <a class="header-anchor" href="#workbuddy-一键自动识别-免复制粘贴" aria-label="Permalink to &quot;WorkBuddy 一键自动识别（免复制粘贴）&quot;">​</a></h3><p>如果你在电脑上安装了 WorkBuddy，可以免去来回复制粘贴：</p><ol><li><strong>首次配置</strong>：打开首页 <strong>设置… → WorkBuddy 自动识别 → 连接 WorkBuddy</strong>（只需连接一次）。</li><li><strong>发起识别</strong>：在“从图片导入”窗口放好图片后，点击 <strong>交给 WorkBuddy 识别</strong>。</li><li><strong>触发并自动回填</strong>：切到 WorkBuddy 对话框中说一句 <code>导入题目</code>，识别与校验结果会自动传回导入窗口，检查后直接导入即可。</li></ol><h2 id="_3-从墨案导入" tabindex="-1">3. 从墨案导入 <a class="header-anchor" href="#_3-从墨案导入" aria-label="Permalink to &quot;3. 从墨案导入&quot;">​</a></h2><p>如果你之前在“墨案”平台整理过教案，可以直接整篇或整个文件夹迁移过来：</p><ol><li>在首页点击 <strong>从墨案导入…</strong>（或顶部菜单 <strong>文件 → 从墨案导入…</strong>），打开内置墨案窗口并登录账号（登录状态会自动保留）。</li><li><strong>单篇导入</strong>：在窗口中打开一篇要迁移的教案，软件会询问是否导入。</li><li><strong>整夹批量导入</strong>：进入墨案教案所在文件夹，点击窗口顶部菜单 <strong>导入 → 导入当前文件夹的全部教案</strong>，即可一次性全部导入。</li></ol><h3 id="迁移说明" tabindex="-1">迁移说明 <a class="header-anchor" href="#迁移说明" aria-label="Permalink to &quot;迁移说明&quot;">​</a></h3><ul><li>迁移后的教学案默认使用 <strong>数学教学案 V1.0</strong> 预设，保存路径为 <code>教学案库\\墨案导入</code>（批量导入文件夹时会按文件夹名归档），导入后自动在主窗口打开。</li><li>题目、变式题（<code>a. b. c.</code>）、答案、解析、LaTeX 公式、从 Word 粘贴的 MathML 公式、图片、作答留白、换页、难度（默认隐藏）以及解析中的 <code>审题：…</code>、标为“重点”的题目都会完整保留。</li><li>选项排在表格里的选择题会自动拆格取出选项（实验数据等普通表格则继续保留）。</li><li>若遇网络切换或页面加载异常，可在墨案窗口 <strong>页面</strong> 菜单中使用 <strong>强制刷新（忽略缓存）</strong> 或 <strong>清除登录状态与缓存并刷新</strong>；若导入异常，可通过 <strong>导入 → 保存诊断文件</strong> 保存脱敏诊断包反馈排查。</li></ul><h2 id="_4-导入知识点" tabindex="-1">4. 导入知识点 <a class="header-anchor" href="#_4-导入知识点" aria-label="Permalink to &quot;4. 导入知识点&quot;">​</a></h2><p>如果需要往“知识梳理”栏目或知识点手册中批量录入知识条目：</p><ul><li>点击工具栏 <strong>导入知识点 ▾</strong>，同样支持 <strong>Word 文档</strong> 与 <strong>图片</strong> 两种来源。</li><li>按照知识点模式识别时，以 <code>一、……</code> 写成的标题后紧跟正文会被识别为一个知识点块，条目下以 <code>1.</code> 开头的序号列表不会被误拆成题目。</li></ul>',23)])])}const _=r(n,[["render",s]]);export{u as __pageData,_ as default};
